import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.CWpttWmj.js";const g=JSON.parse('{"title":"Renewals & expiry","description":"","frontmatter":{},"headers":[],"relativePath":"guide/renewals.md","filePath":"guide/renewals.md","lastUpdated":null}'),n={name:"guide/renewals.md"};function r(o,e,d,h,l,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="renewals-expiry" tabindex="-1">Renewals &amp; expiry <a class="header-anchor" href="#renewals-expiry" aria-label="Permalink to &quot;Renewals &amp; expiry&quot;">​</a></h1><p>A <code>.arc</code> name is a lease, not a freehold. It has an expiry date, and keeping it means renewing before that date passes — plus a 90-day safety net afterwards.</p><p>This page is the one most worth reading carefully. The grace period is the single most misunderstood part of the protocol.</p><h2 id="the-three-states" tabindex="-1">The three states <a class="header-anchor" href="#the-three-states" aria-label="Permalink to &quot;The three states&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   registered          in grace              available</span></span>
<span class="line"><span>├────────────────────┼──────────────────┼─────────────────────►</span></span>
<span class="line"><span>                  expiry          expiry + 90 days</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Condition</th><th>Who can register it</th><th>Can the owner renew?</th></tr></thead><tbody><tr><td><strong>Registered</strong></td><td><code>expiry &gt; now</code></td><td>Nobody</td><td>Yes</td></tr><tr><td><strong>In grace</strong></td><td><code>now &gt;= expiry</code> and <code>now &lt;= expiry + 90 days</code></td><td>Nobody</td><td><strong>Yes</strong></td></tr><tr><td><strong>Available</strong></td><td><code>now &gt; expiry + 90 days</code></td><td>Anyone</td><td>No — it&#39;s gone</td></tr></tbody></table><p>The contract expresses availability as a single line:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> available</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> view</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> returns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> expiries[id] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRACE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>GRACE</code> is a hard constant of <strong>90 days</strong> in the registrar. It is not configurable and cannot be changed by the contract owner.</p><h2 id="what-the-grace-period-is-for" tabindex="-1">What the grace period is for <a class="header-anchor" href="#what-the-grace-period-is-for" aria-label="Permalink to &quot;What the grace period is for&quot;">​</a></h2><p>Missing a renewal by a day should not cost you your identity. The 90-day window means an expired name is not immediately up for grabs — it stays locked to its previous owner, who can renew it at any point during those three months and carry on as though nothing happened.</p><p>Nobody else can register the name during grace. Attempting to reverts with <code>taken</code>.</p><div class="danger custom-block"><p class="custom-block-title">An expired name stops working immediately</p><p>The grace period protects your <em>claim</em> on the name. It does not keep the name functional.</p><p>The moment the expiry passes:</p><ul><li><code>registrar.ownerOf(id)</code> <strong>reverts with <code>expired</code></strong> — it does not return the old owner.</li><li>Any integration that reads ownership sees a failure, not a stale value.</li><li>Wallets and apps that check liveness will stop resolving the name.</li></ul><p>So a name in grace is a name that is broken but recoverable. Do not treat the 90 days as an extension of normal service.</p></div><h2 id="renewing" tabindex="-1">Renewing <a class="header-anchor" href="#renewing" aria-label="Permalink to &quot;Renewing&quot;">​</a></h2><p>Anyone can renew any name — renewal is not restricted to the owner. There is no risk in this: a renewal only extends the expiry, it never changes ownership or records. If a friend renews your name for you, you still own it.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renew</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nm, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">payable</span></span></code></pre></div><p>The cost uses exactly the same tiered pricing as registration, prorated over the duration. See <a href="/docs/guide/pricing.html">Pricing &amp; rarity</a>.</p><p>Renewal is a <strong>single transaction</strong> — there is no commit-reveal step, because there is nothing to front-run. The name is already owned.</p><p>Duration bounds are the same as registration: 28 days minimum, 100 years maximum, or the call reverts with <code>duration</code>. Overpayment is refunded in the same transaction.</p><h3 id="in-the-app" tabindex="-1">In the app <a class="header-anchor" href="#in-the-app" aria-label="Permalink to &quot;In the app&quot;">​</a></h3><p>Open <strong>My names</strong>, find the name, press <strong>Renew</strong>, choose a duration, confirm. The new expiry is the old expiry plus the duration — renewing early does not waste the time you have left, it stacks on top of it.</p><h3 id="renewing-after-expiry" tabindex="-1">Renewing after expiry <a class="header-anchor" href="#renewing-after-expiry" aria-label="Permalink to &quot;Renewing after expiry&quot;">​</a></h3><p>Still allowed, for 90 days:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(expiries[id] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRACE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expired&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Past that, <code>renew</code> reverts with <code>expired</code> and the name is genuinely gone. Note the asymmetry: the registrar&#39;s <code>available()</code> uses <code>&lt;</code> and <code>renew</code> uses <code>&gt;=</code>, so the boundary is handled consistently — there is no window where a name can be neither renewed nor registered.</p><h2 id="when-a-name-is-released" tabindex="-1">When a name is released <a class="header-anchor" href="#when-a-name-is-released" aria-label="Permalink to &quot;When a name is released&quot;">​</a></h2><p>Once <code>expiry + 90 days</code> has passed, the name becomes registerable by anyone through the ordinary <a href="/docs/guide/registering.html">registration flow</a>. There is no auction, no premium decay, and no priority for the previous owner. First valid commit-reveal wins.</p><p>The app shows the exact release date on any name in grace, so you can see when a name you want frees up. Nothing reserves it for you at that moment — you have to be there.</p><h2 id="what-happens-to-the-records" tabindex="-1">What happens to the records <a class="header-anchor" href="#what-happens-to-the-records" aria-label="Permalink to &quot;What happens to the records&quot;">​</a></h2><p>Registering an expired name mints a fresh token to the new owner, and the controller binds the resolver and sets the address record to point at <em>them</em>.</p><p>Text records written by the previous owner are stored per-node and are <strong>not automatically cleared</strong>. A new owner should overwrite or clear any records they don&#39;t want, and integrators should not assume a record was written by the current owner. See <a href="/docs/guide/records.html">Records &amp; profile</a>.</p><h2 id="not-losing-a-name" tabindex="-1">Not losing a name <a class="header-anchor" href="#not-losing-a-name" aria-label="Permalink to &quot;Not losing a name&quot;">​</a></h2><p>The protocol has no notifications, no auto-renew and no recovery. Practical measures:</p><ol><li><strong>Register for longer.</strong> Duration costs the same per year whether you buy one year or ten, and a 5-year registration is four fewer chances to forget. One transaction either way.</li><li><strong>Put the expiry in a calendar,</strong> with a reminder a month ahead — not a day ahead.</li><li><strong>Check the app periodically.</strong> <strong>My names</strong> shows every expiry date you hold.</li><li><strong>Watch on-chain.</strong> Read <code>nameExpires(tokenId)</code> from the registrar, or poll <code>GET /api/v1/domains/:name</code> and alert on <code>expiresAt</code>. See <a href="/docs/api/endpoints.html">API endpoints</a>.</li><li><strong>Renew from a wallet you actually use.</strong> Renewal doesn&#39;t require the owning wallet, so a name held in cold storage can be renewed from a hot wallet without touching the hardware key.</li></ol><p>That last point is worth repeating: <strong>you never need to expose the wallet holding a valuable name in order to renew it.</strong></p><h2 id="revert-reference" tabindex="-1">Revert reference <a class="header-anchor" href="#revert-reference" aria-label="Permalink to &quot;Revert reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Revert</th><th>Cause</th></tr></thead><tbody><tr><td><code>expired</code> (on <code>renew</code>)</td><td>Past expiry + 90 days. The name is released; register it normally if it&#39;s still free.</td></tr><tr><td><code>expired</code> (on <code>ownerOf</code>)</td><td>The name is past its expiry, including during grace. Read <code>nameExpires</code> instead.</td></tr><tr><td><code>duration</code></td><td>Renewal duration outside 28 days – 100 years.</td></tr><tr><td><code>underpaid</code></td><td><code>msg.value</code> below the quoted renewal price.</td></tr><tr><td><code>taken</code></td><td>You tried to register a name that is registered or in grace.</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/pricing.html">Pricing &amp; rarity</a> — what renewal costs.</li><li><a href="/docs/guide/claiming.html">Claiming a name</a> — registering a name that has just been released.</li><li><a href="/docs/guide/ownership.html">Ownership &amp; transfers</a> — moving a name to another wallet.</li></ul>`,39)])])}const y=a(n,[["render",r]]);export{g as __pageData,y as default};
